/**
 * C4 (SPEC-0001): replay traces generated by the Lean model (model/) against the
 * TypeScript implementation and compare the observations after every step.
 *
 * Traces: JSON Lines in the format of SPEC-0001 §4. Path from PREPARE_DEV_TRACES or
 * model/traces/depth-6.jsonl. The test is skipped (and says so) when the file is missing.
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { parseMarkdown, serializeMarkdown, type Event } from "@prepare-dev/core";
import { Runtime } from "./runtime.js";
import { RuntimeError, SimulatedCrash } from "./errors.js";
import type { ApplyStage } from "./questions.js";

interface TraceLine {
  trace: number;
  step: number;
  action: {
    type: "create_question" | "edit" | "save_answer" | "ack" | "close" | "apply" | "recover";
    question?: string;
    subjects?: string[];
    record?: string;
    answer?: string;
    crash_after?: null | "intent" | "decision" | "question";
  };
  observe: {
    inflight: boolean;
    pending: string[];
    committed: Record<string, string>;
    closed: string[];
    stale: string[];
    public_decisions: string[];
    result: string;
  };
}

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const tracesFile = process.env.PREPARE_DEV_TRACES ?? path.join(repoRoot, "model", "traces", "depth-4.jsonl");

function loadTraces(): Map<number, TraceLine[]> {
  const out = new Map<number, TraceLine[]>();
  for (const line of fs.readFileSync(tracesFile, "utf8").split("\n")) {
    if (!line.trim()) continue;
    const t = JSON.parse(line) as TraceLine;
    if (!out.has(t.trace)) out.set(t.trace, []);
    out.get(t.trace)!.push(t);
  }
  return out;
}

/** Observation computed from the persisted files only (works while the "daemon" is down). */
function observeFromDisk(root: string, ids: IdMap): Omit<TraceLine["observe"], "result"> {
  const events: Event[] = fs
    .readFileSync(path.join(root, "prepare", "events.jsonl"), "utf8")
    .split("\n")
    .filter((l) => l.trim())
    .map((l) => JSON.parse(l) as Event);
  const intents = events.filter((e) => e.type === "apply.intent");
  const committedTx = new Set(events.filter((e) => e.type === "apply.commit").map((e) => (e as { txid: string }).txid));
  const abortedTx = new Set(events.filter((e) => e.type === "apply.abort").map((e) => (e as { txid: string }).txid));
  const inflight = intents.some((i) => !committedTx.has(i.txid) && !abortedTx.has(i.txid));
  const committed: Record<string, string> = {};
  for (const i of intents) if (committedTx.has(i.txid)) committed[ids.modelAnswer(i.answer_id)] = ids.modelDecision(i.decision_id);
  const pending: string[] = [];
  const closed: string[] = [];
  const stale: string[] = [];
  const qdir = path.join(root, "prepare", "questions");
  for (const f of fs.existsSync(qdir) ? fs.readdirSync(qdir).filter((n) => n.endsWith(".json")) : []) {
    const q = JSON.parse(fs.readFileSync(path.join(qdir, f), "utf8")) as { answers: Array<{ answer_id: string; stale: boolean; closed: unknown }> };
    for (const a of q.answers) {
      const m = ids.modelAnswer(a.answer_id);
      if (a.closed) closed.push(m);
      if (a.stale) stale.push(m);
      if (!a.closed && !(m in committed)) pending.push(m);
    }
  }
  const ddir = path.join(root, "prepare", "decisions");
  const public_decisions: string[] = [];
  for (const f of fs.existsSync(ddir) ? fs.readdirSync(ddir).filter((n) => n.endsWith(".md")) : []) {
    const { frontmatter } = parseMarkdown<{ id: string; txid?: string }>(fs.readFileSync(path.join(ddir, f), "utf8"));
    if (!frontmatter.txid || committedTx.has(frontmatter.txid)) public_decisions.push(ids.modelDecision(frontmatter.id));
  }
  return { inflight, pending: pending.sort(), committed, closed: closed.sort(), stale: stale.sort(), public_decisions: public_decisions.sort() };
}

class IdMap {
  records = new Map<string, string>(); // R1 -> REQ-0001
  questions = new Map<string, string>(); // Q1 -> Q-0001
  answers = new Map<string, string>(); // A1 -> ANS-0001-1
  answersRev = new Map<string, string>();
  modelAnswer(impl: string): string {
    return this.answersRev.get(impl) ?? impl;
  }
  modelDecision(impl: string): string {
    const m = /^DEC-0*(\d+)$/.exec(impl);
    return m ? `D${m[1]}` : impl;
  }
}

function externalEdit(root: string, rel: string): void {
  const abs = path.join(root, rel);
  const { frontmatter, body } = parseMarkdown(fs.readFileSync(abs, "utf8"));
  fs.writeFileSync(abs, serializeMarkdown({ frontmatter, body: `${body}\n編集 ${Date.now()} ${Math.random()}\n` }));
}

const decision = { title: "判断", body: "理由\n", chosen: "a", alternatives: [] as string[] };

function replay(lines: TraceLine[]): Array<{ step: number; action: TraceLine["action"]; expected: TraceLine["observe"]; actual: TraceLine["observe"] }> {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "prepare-dev-conf-"));
  const ids = new IdMap();
  let rt: Runtime | null = Runtime.open(root);
  for (const r of ["R1", "R2"]) {
    const rec = rt.store.createRecord("requirement", { title: r }, `${r}\n`);
    ids.records.set(r, rec.id);
  }
  const mismatches: Array<{ step: number; action: TraceLine["action"]; expected: TraceLine["observe"]; actual: TraceLine["observe"] }> = [];
  const up = (): Runtime => {
    if (!rt) throw new Error("daemon is down; the model must emit recover first");
    return rt;
  };
  for (const line of lines) {
    const a = line.action;
    let result = "ok";
    try {
      switch (a.type) {
        case "create_question": {
          const q = up().questions.create({
            kind: "single_choice",
            prompt: a.question!,
            subjects: a.subjects!.map((s) => ids.records.get(s)!),
            options: [{ key: "a", label: "a" }],
          });
          ids.questions.set(a.question!, q.id);
          break;
        }
        case "edit": {
          const id = ids.records.get(a.record!)!;
          externalEdit(root, path.join("prepare", "requirements", `${id}.md`));
          break;
        }
        case "save_answer": {
          const { answer } = up().questions.answer(ids.questions.get(a.question!)!, { choice: ["a"] });
          ids.answers.set(a.answer!, answer.answer_id);
          ids.answersRev.set(answer.answer_id, a.answer!);
          break;
        }
        case "ack": {
          const qid = questionOf(ids, a.answer!);
          up().questions.ack(qid, ids.answers.get(a.answer!)!);
          break;
        }
        case "close": {
          const qid = questionOf(ids, a.answer!);
          up().questions.close(qid, ids.answers.get(a.answer!)!, "trace");
          break;
        }
        case "apply": {
          const qid = questionOf(ids, a.answer!);
          const hooks = a.crash_after
            ? {
                afterStage: (s: ApplyStage) => {
                  if (s === a.crash_after) throw new SimulatedCrash(s);
                },
              }
            : undefined;
          const r = up().questions.apply(qid, ids.answers.get(a.answer!)!, { decision }, hooks);
          result = r.status; // applied | already_applied
          break;
        }
        case "recover": {
          if (rt && !rt.store.inflightIntents().length) {
            result = "noop";
            break;
          }
          rt = Runtime.open(root);
          const rec = rt.recovery.recovered[0];
          result = !rec ? "noop" : rec.outcome === "forward" ? "recovered_forward" : "recovered_abort";
          break;
        }
      }
    } catch (e) {
      if (e instanceof SimulatedCrash) {
        result = "crashed";
        rt = null;
      } else if (e instanceof RuntimeError) {
        result = e.code === "stale" ? "rejected_stale" : e.code === "closed" ? "rejected_closed" : e.code === "inflight" ? "rejected_inflight" : `error:${e.code}`;
      } else throw e;
    }
    const actual = { ...observeFromDisk(root, ids), result };
    const expected = line.observe;
    const compareResult = a.type === "apply" || a.type === "recover";
    const canon = (o: Record<string, string>): string => JSON.stringify(Object.keys(o).sort().map((k) => [k, o[k]]));
    const same =
      actual.inflight === expected.inflight &&
      JSON.stringify(actual.pending) === JSON.stringify([...expected.pending].sort()) &&
      canon(actual.committed) === canon(expected.committed) &&
      JSON.stringify(actual.closed) === JSON.stringify([...expected.closed].sort()) &&
      JSON.stringify(actual.stale) === JSON.stringify([...expected.stale].sort()) &&
      JSON.stringify(actual.public_decisions) === JSON.stringify([...expected.public_decisions].sort()) &&
      (!compareResult || actual.result === expected.result);
    if (!same) {
      mismatches.push({ step: line.step, action: a, expected, actual });
      break;
    }
  }
  fs.rmSync(root, { recursive: true, force: true });
  return mismatches;
}

function questionOf(ids: IdMap, modelAnswer: string): string {
  const impl = ids.answers.get(modelAnswer)!;
  const qnum = impl.replace(/^ANS-/, "").replace(/-\d+$/, "");
  return `Q-${qnum}`;
}

describe("model traces", () => {
  const exists = fs.existsSync(tracesFile);
  it.skipIf(!exists)(`C4: implementation agrees with the Lean model on every generated trace (${path.relative(repoRoot, tracesFile)})`, { timeout: 1_800_000 }, () => {
    const traces = loadTraces();
    expect(traces.size).toBeGreaterThan(0);
    const failures: Array<{ trace: number; mismatch: ReturnType<typeof replay>[number] }> = [];
    let steps = 0;
    for (const [idx, lines] of traces) {
      steps += lines.length;
      const m = replay(lines);
      if (m.length) failures.push({ trace: idx, mismatch: m[0]! });
    }
    const summary = { traces: traces.size, steps, failures: failures.length };
    fs.mkdirSync(path.join(repoRoot, ".prepare-dev", "tmp"), { recursive: true });
    fs.writeFileSync(path.join(repoRoot, ".prepare-dev", "tmp", "conformance-summary.json"), JSON.stringify({ ...summary, first_failures: failures.slice(0, 5) }, null, 2));
    expect(failures, JSON.stringify(failures.slice(0, 3), null, 2)).toEqual([]);
  });
  if (!exists) {
    it("traces file missing", () => {
      console.warn(`conformance traces not found: ${tracesFile} (generate with: cd model && lake exe prepare-model gen --depth 6 > traces/depth-6.jsonl)`);
    });
  }
});
